replacements.new:
async function createCommit() {
  if (!state.commitReview) return;
  state.busy = true;
  commitConfirm.disabled = true;
  try {
    const result = await request('/commit', { token: state.commitReview.token, message: state.commitReview.message });
    state.commitReview = null; commitReview.hidden = true;
    await refresh();
    if (result?.state === 'unknown') setStatus(commitUnknownMessage(result), 'error');
    else setStatus(`Local commit created at ${result.commitOid.slice(0, 12)}. No hooks or signing were run.`);
  } catch (error) {
    state.commitReview = null; commitReview.hidden = true;
    setStatus(error.unknown || error.code === 'unknown' ? commitUnknownMessage(error) : error.message, 'error');
  }
  finally { state.busy = false; commitConfirm.disabled = false; }
}
